<?php                                                                                                                                                                                                                                                               
    /**                                                                                                                                                                                                                                                                 
     * FHIR AdverseEvent Resource Mapper                                                                                                                                                                                                                                
     * Translates HL7 FHIR R4 AdverseEvent JSON into HATUA CTR SAE payload format.                                                                                                                                                                                      
     */                                                                                                                                                                                                                                                                 
    class FhirAdverseEventMapper                                                                                                                                                                                                                                        
    {                                                                                                                                                                                                                                                                   
        public static function toSaePayload($fhir = array())                                                                                                                                                                                                            
        {                                                                                                                                                                                                                                                               
            if (empty($fhir) || !is_array($fhir)) {                                                                                                                                                                                                                     
                return array();                                                                                                                                                                                                                                         
            }                                                                                                                                                                                                                                                           
                                                                                                                                                                                                                                                                        
            $sae = array(                                                                                                                                                                                                                                               
                'form_type' => 'SAE',                                                                                                                                                                                                                                   
                'protocol_urn' => self::extractProtocolUrn($fhir),                                                                                                                                                                                                      
                'patient_initials' => self::extractPatientInitials($fhir),                                                                                                                                                                                              
                'reaction_onset' => self::extractReactionDate($fhir),                                                                                                                                                                                                   
                'reaction_description' => self::extractReactionDescription($fhir),                                                                                                                                                                                      
                'causality' => 'Probable/Likely',                                                                                                                                                                                                                       
            );                                                                                                                                                                                                                                                          
                                                                                                                                                                                                                                                                        
            $seriousness = self::extractSeriousnessFlags($fhir);                                                                                                                                                                                                        
            $sae = array_merge($sae, $seriousness);                                                                                                                                                                                                                     
            $suspectedDrugs = self::extractSuspectedDrugs($fhir);                                                                                                                                                                                                       
                                                                                                                                                                                                                                                                        
            if (!empty($fhir['recorder']['display'])) {                                                                                                                                                                                                                 
                $sae['reporter_name'] = trim((string)$fhir['recorder']['display']);                                                                                                                                                                                     
            }                                                                                                                                                                                                                                                           
                                                                                                                                                                                                                                                                        
            return array(                                                                                                                                                                                                                                               
                'protocol_urn' => $sae['protocol_urn'],                                                                                                                                                                                                                 
                'Sae' => $sae,                                                                                                                                                                                                                                          
                'suspected_drugs' => $suspectedDrugs,                                                                                                                                                                                                                   
                'concomittant_drugs' => array()                                                                                                                                                                                                                         
            );                                                                                                                                                                                                                                                          
        }                                                                                                                                                                                                                                                               
                                                                                                                                                                                                                                                                        
        private static function extractProtocolUrn($fhir)                                                                                                                                                                                                               
        {                                                                                                                                                                                                                                                               
            if (!empty($fhir['study']) && is_array($fhir['study'])) {                                                                                                                                                                                                   
                foreach ($fhir['study'] as $studyRef) {                                                                                                                                                                                                                 
                    if (!empty($studyRef['identifier']['value'])) {                                                                                                                                                                                                     
                        return trim((string)$studyRef['identifier']['value']);                                                                                                                                                                                          
                    }                                                                                                                                                                                                                                                   
                    if (!empty($studyRef['display'])) {                                                                                                                                                                                                                 
                        return trim((string)$studyRef['display']);                                                                                                                                                                                                      
                    }                                                                                                                                                                                                                                                   
                }                                                                                                                                                                                                                                                       
            }                                                                                                                                                                                                                                                           
            if (!empty($fhir['identifier']) && is_array($fhir['identifier'])) {                                                                                                                                                                                         
                foreach ($fhir['identifier'] as $id) {                                                                                                                                                                                                                  
                    if (!empty($id['value'])) {                                                                                                                                                                                                                         
                        return trim((string)$id['value']);                                                                                                                                                                                                              
                    }                                                                                                                                                                                                                                                   
                }                                                                                                                                                                                                                                                       
            }                                                                                                                                                                                                                                                           
            return '';                                                                                                                                                                                                                                                  
        }                                                                                                                                                                                                                                                               
                                                                                                                                                                                                                                                                        
        private static function extractPatientInitials($fhir)                                                                                                                                                                                                           
        {                                                                                                                                                                                                                                                               
            if (!empty($fhir['subject']['display'])) {                                                                                                                                                                                                                  
                return trim((string)$fhir['subject']['display']);                                                                                                                                                                                                       
            }                                                                                                                                                                                                                                                           
            if (!empty($fhir['subject']['reference'])) {                                                                                                                                                                                                                
                return trim((string)$fhir['subject']['reference']);                                                                                                                                                                                                     
            }                                                                                                                                                                                                                                                           
            return '';                                                                                                                                                                                                                                                  
        }                                                                                                                                                                                                                                                               
                                                                                                                                                                                                                                                                        
        private static function extractReactionDate($fhir)                                                                                                                                                                                                              
        {                                                                                                                                                                                                                                                               
            if (!empty($fhir['date'])) {                                                                                                                                                                                                                                
                $timestamp = strtotime($fhir['date']);                                                                                                                                                                                                                  
                if ($timestamp !== false) {                                                                                                                                                                                                                             
                    return date('Y-m-d', $timestamp);                                                                                                                                                                                                                   
                }                                                                                                                                                                                                                                                       
            }                                                                                                                                                                                                                                                           
            return date('Y-m-d');                                                                                                                                                                                                                                       
        }                                                                                                                                                                                                                                                               
                                                                                                                                                                                                                                                                        
        private static function extractReactionDescription($fhir)                                                                                                                                                                                                       
        {                                                                                                                                                                                                                                                               
            if (!empty($fhir['event']['text'])) {                                                                                                                                                                                                                       
                return trim((string)$fhir['event']['text']);                                                                                                                                                                                                            
            }                                                                                                                                                                                                                                                           
            if (!empty($fhir['event']['coding'][0]['display'])) {                                                                                                                                                                                                       
                return trim((string)$fhir['event']['coding'][0]['display']);                                                                                                                                                                                            
            }                                                                                                                                                                                                                                                           
            return 'Adverse Event reported via FHIR';                                                                                                                                                                                                                   
        }                                                                                                                                                                                                                                                               
                                                                                                                                                                                                                                                                        
        private static function extractSeriousnessFlags($fhir)                                                                                                                                                                                                          
        {                                                                                                                                                                                                                                                               
            $flags = array(                                                                                                                                                                                                                                             
                'patient_died' => 0,                                                                                                                                                                                                                                    
                'prolonged_hospitalization' => 0,                                                                                                                                                                                                                       
                'incapacity' => 0,                                                                                                                                                                                                                                      
                'life_threatening' => 0,                                                                                                                                                                                                                                
                'reaction_other' => 0,                                                                                                                                                                                                                                  
            );                                                                                                                                                                                                                                                          
                                                                                                                                                                                                                                                                        
            $seriousnessText = '';                                                                                                                                                                                                                                      
            if (!empty($fhir['seriousness']['coding'][0]['code'])) {                                                                                                                                                                                                    
                $seriousnessText .= ' ' . $fhir['seriousness']['coding'][0]['code'];                                                                                                                                                                                    
            }                                                                                                                                                                                                                                                           
            if (!empty($fhir['seriousness']['coding'][0]['display'])) {                                                                                                                                                                                                 
                $seriousnessText .= ' ' . $fhir['seriousness']['coding'][0]['display'];                                                                                                                                                                                 
            }                                                                                                                                                                                                                                                           
            if (!empty($fhir['seriousness']['text'])) {                                                                                                                                                                                                                 
                $seriousnessText .= ' ' . $fhir['seriousness']['text'];                                                                                                                                                                                                 
            }                                                                                                                                                                                                                                                           
                                                                                                                                                                                                                                                                        
            $lower = strtolower($seriousnessText);                                                                                                                                                                                                                      
            if (strpos($lower, 'death') !== false || strpos($lower, 'fatal') !== false) {                                                                                                                                                                               
                $flags['patient_died'] = 1;                                                                                                                                                                                                                             
            }                                                                                                                                                                                                                                                           
            if (strpos($lower, 'hospital') !== false) {                                                                                                                                                                                                                 
                $flags['prolonged_hospitalization'] = 1;                                                                                                                                                                                                                
            }                                                                                                                                                                                                                                                           
            if (strpos($lower, 'life') !== false) {                                                                                                                                                                                                                     
                $flags['life_threatening'] = 1;                                                                                                                                                                                                                         
            }                                                                                                                                                                                                                                                           
            if (strpos($lower, 'incapacity') !== false || strpos($lower, 'disability') !== false) {                                                                                                                                                                     
                $flags['incapacity'] = 1;                                                                                                                                                                                                                               
            }                                                                                                                                                                                                                                                           
                                                                                                                                                                                                                                                                        
            if (!in_array(1, $flags, true)) {                                                                                                                                                                                                                           
                $flags['reaction_other'] = 1;                                                                                                                                                                                                                           
            }                                                                                                                                                                                                                                                           
                                                                                                                                                                                                                                                                        
            return $flags;                                                                                                                                                                                                                                              
        }                                                                                                                                                                                                                                                               
                                                                                                                                                                                                                                                                        
        private static function extractSuspectedDrugs($fhir)                                                                                                                                                                                                            
        {                                                                                                                                                                                                                                                               
            $drugs = array();                                                                                                                                                                                                                                           
            if (!empty($fhir['suspectEntity']) && is_array($fhir['suspectEntity'])) {                                                                                                                                                                                   
                foreach ($fhir['suspectEntity'] as $entity) {                                                                                                                                                                                                           
                    $drugName = '';                                                                                                                                                                                                                                     
                    if (!empty($entity['instance']['display'])) {                                                                                                                                                                                                       
                        $drugName = trim((string)$entity['instance']['display']);                                                                                                                                                                                       
                    } elseif (!empty($entity['instance']['concept']['text'])) {                                                                                                                                                                                         
                        $drugName = trim((string)$entity['instance']['concept']['text']);                                                                                                                                                                               
                    }                                                                                                                                                                                                                                                   
                                                                                                                                                                                                                                                                        
                    if ($drugName !== '') {                                                                                                                                                                                                                             
                        $drugs[] = array(                                                                                                                                                                                                                               
                            'drug_name' => $drugName,                                                                                                                                                                                                                   
                            'causality' => 'Probable/Likely',                                                                                                                                                                                                           
                            'date_started' => date('Y-m-d'),                                                                                                                                                                                                            
                        );                                                                                                                                                                                                                                              
                    }                                                                                                                                                                                                                                                   
                }                                                                                                                                                                                                                                                       
            }                                                                                                                                                                                                                                                           
                                                                                                                                                                                                                                                                        
            if (empty($drugs)) {                                                                                                                                                                                                                                        
                $drugs[] = array(                                                                                                                                                                                                                                       
                    'drug_name' => 'Investigational Product',                                                                                                                                                                                                           
                    'causality' => 'Probable/Likely',                                                                                                                                                                                                                   
                    'date_started' => date('Y-m-d'),                                                                                                                                                                                                                    
                );                                                                                                                                                                                                                                                      
            }                                                                                                                                                                                                                                                           
                                                                                                                                                                                                                                                                        
            return $drugs;                                                                                                                                                                                                                                              
        }                                                                                                                                                                                                                                                               
    }                                                        